const path=require('node:path');
module.exports=async({page,assert,patch,sampleSlow,output})=>{
 const root=page.getByTestId('module-update-ready'),label=root.locator('.module-update-pending');
 const api=async(method,arg)=>{await page.evaluate(({method,arg})=>window.moduleUpdateFixture[method](arg),{method,arg});await page.evaluate(()=>new Promise(r=>requestAnimationFrame(r)))};
 const reset=async(version=null)=>{await api('reset',version);await root.scrollIntoViewIfNeeded();await root.getByText('Fixture module',{exact:true}).waitFor();await page.waitForTimeout(30)};
 const file=async(keyboard=false)=>{const trigger=root.getByRole('button',{name:'Install update…',exact:true});if(keyboard){await trigger.focus();await page.keyboard.press('Enter');await page.getByRole('menuitem',{name:'From file…',exact:true}).focus();await page.keyboard.press('Enter')}else{await trigger.click();await page.getByRole('menuitem',{name:'From file…',exact:true}).click()}await page.waitForFunction(()=>window.moduleUpdateFixture.snapshot().pending)};
 const url=async(keyboard=false)=>{await root.getByRole('button',{name:'Install update…',exact:true}).click();await page.getByRole('menuitem',{name:'From URL…',exact:true}).click();await page.getByRole('textbox',{name:'Module update URL'}).fill('https://example.test/fixture.zqmodule');if(keyboard)await page.getByRole('textbox',{name:'Module update URL'}).press('Enter');else await page.getByRole('button',{name:'Download update',exact:true}).click();await page.waitForFunction(()=>window.moduleUpdateFixture.snapshot().pending)};
 const instant=async()=>{await label.waitFor();assert.equal(await label.getAttribute('data-feedback'),'idle');assert.equal(await label.evaluate(e=>e.getAnimations().length),0)};
 const cue=async()=>{await page.waitForFunction(()=>document.querySelector('[data-testid=module-update-ready] .module-update-pending[data-feedback=visible]'));return label.evaluate(e=>{const s=getComputedStyle(e);return {duration:s.transitionDuration,property:s.transitionProperty,origin:s.transformOrigin,transform:s.transform}})};
 await reset('1.1.0');await instant();await file();await api('finish',{version:'1.1.0'});await instant();
 await reset();await file();await api('finish',{});const standard=await cue();assert.equal(standard.duration,'0.15s, 0.15s');assert(standard.origin.startsWith('0px '));const rowBox=await root.locator('.module-version-row').boundingBox();await sampleSlow('module-update-ready','[data-testid=module-update-ready] .module-update-pending');assert.deepEqual(await root.locator('.module-version-row').boundingBox(),rowBox);await page.waitForTimeout(250);await instant();
 // A later list/revisit must not replay a pending version.
 await api('patch',{hidden:true});await api('patch',{hidden:false});await instant();await api('patch',{mounted:false});await api('patch',{mounted:true});await instant();
 await reset();await file(true);await api('finish',{});await instant();
 await reset();await url();await api('finish',{});const dialog=page.getByRole('dialog',{name:'Download module update'});assert.equal(await dialog.count(),1);assert.equal(await label.getAttribute('data-feedback'),'idle');await dialog.waitFor({state:'detached'});await cue();assert.equal(await root.getByRole('button',{name:'Install update…',exact:true}).evaluate(e=>e===document.activeElement),true);await page.waitForTimeout(250);await instant();
 await reset();await url(true);await api('finish',{});await page.getByRole('dialog').waitFor({state:'detached'});await instant();
 await reset();await file();await api('finish',{cancel:true});assert.equal(await label.count(),0);
 await file();await api('finish',{error:true});await root.getByRole('alert').waitFor();assert.equal(await label.count(),0);
 await reset();await file();await api('finish',{mismatch:true});await instant();assert.match(await label.innerText(),/9.9.9/);
 await reset();await file();await api('patch',{hidden:true});await api('patch',{hidden:false});await api('finish',{});await instant();
 await reset();await file();await api('patch',{closing:true});await api('patch',{closing:false});await api('finish',{});await instant();assert.equal(await root.getByRole('button',{name:'Install update…',exact:true}).isEnabled(),true);
 await reset();await file();await page.evaluate(()=>{Object.defineProperty(document,'hidden',{configurable:true,value:true});Object.defineProperty(document,'visibilityState',{configurable:true,value:'hidden'});document.dispatchEvent(new Event('visibilitychange'));delete document.hidden;delete document.visibilityState;document.dispatchEvent(new Event('visibilitychange'))});await api('finish',{});await instant();
 await reset();await file();await api('patch',{mounted:false});await api('finish',{});await api('patch',{mounted:true});await instant();
 await reset();await file();await api('patch',{clipped:true});await api('finish',{});await instant();await api('patch',{clipped:false});await instant();
 await reset();await root.getByRole('button',{name:'Actions for Fixture module'}).click();await page.getByRole('menuitem',{name:'Roll back Fixture module',exact:true}).click();await api('finish',{});await instant();
 await page.emulateMedia({reducedMotion:'reduce'});await reset();await file();await api('finish',{});const reduced=await cue();assert.equal(reduced.duration,'0.08s');assert.equal(reduced.property,'opacity');assert.equal(reduced.transform,'none');await page.waitForTimeout(150);await instant();await page.emulateMedia({reducedMotion:'no-preference'});await instant();
 await reset();await file();await api('finish',{});await cue();await page.emulateMedia({reducedMotion:'reduce'});await page.waitForFunction(()=>document.querySelector('[data-testid=module-update-ready] .module-update-pending')?.dataset.feedback==='idle',null,{timeout:100});await instant();await page.emulateMedia({reducedMotion:'no-preference'});await instant();
 await page.mouse.move(0,0);await page.evaluate(()=>document.activeElement instanceof HTMLElement&&document.activeElement.blur());await page.waitForTimeout(150);
 for(const theme of ['light','dark']){await patch({theme});await root.screenshot({path:path.join(output,`animation-module-update-${theme}.png`)})}
};
